import {sendEvent} from '@github-ui/hydro-analytics'
import {InfoIcon} from '@primer/octicons-react'
import {Link, LinkButton, VisuallyHidden} from '@primer/react'

import {UPGRADE_FREEZE_LEARN_MORE_URL} from '../../utils/copilot-chat-helpers'
import {copilotFeatureFlags} from '../../utils/copilot-feature-flags'
import {CustomBanner} from './CustomBanner'
import {useEntitlement} from './EntitlementContext'
import {useQuotaBannerImpression} from './use-quota-banner-impression'

export function QuotaExceededBanner() {
  const {plan, resetDate} = useEntitlement()
  useQuotaBannerImpression({variant: 'quota_exceeded', source: 'copilot-chat'})

  const icon = <InfoIcon />

  const content = (
    <span>
      <VisuallyHidden>
        <h2>Usage limit reached</h2>
      </VisuallyHidden>
      You have reached your free plan limit. It will reset on {resetDate}.
      {copilotFeatureFlags.upgradeFreezeEnabled && (
        <>
          {' '}
          Plan upgrades are temporarily unavailable.{' '}
          <Link inline href={UPGRADE_FREEZE_LEARN_MORE_URL}>
            Read more
          </Link>
        </>
      )}
    </span>
  )

  const actions = copilotFeatureFlags.upgradeFreezeEnabled ? undefined : (
    <LinkButton
      as="a"
      href="https://github.com/features/copilot#pricing"
      onClick={() => {
        sendEvent('dotcom_chat.activate', {
          target: 'QUOTA_BANNER_EXCEEDED',
          action: 'upgrade',
          mode: 'assistive',
          plan,
          tokenBasedBillingEnabled: false,
        })
      }}
    >
      Upgrade
    </LinkButton>
  )

  return <CustomBanner icon={icon} content={content} actions={actions} />
}
